"""AFL-style greybox fuzzing primitives and simulation driver."""

from __future__ import annotations

from collections import Counter, defaultdict
from dataclasses import dataclass
from hashlib import sha1
from typing import Dict, Iterable, Iterator, List, Optional, Sequence, Set, Tuple

import numpy as np

from fuzzsim.bitmap import CoverageBitmap
from fuzzsim.mutation import (
    INTERESTING_8,
    INTERESTING_16,
    INTERESTING_32,
    arith_add,
    arith_sub,
    bit_flip,
    byte_flip,
    clone_bytes,
    delete_bytes,
    insert_bytes,
    random_byte,
)
from fuzzsim.seed import TestCase


def _to_unsigned(value: int, width: int) -> int:
    mask = (1 << (width * 8)) - 1
    return value & mask


def _read_int(data: bytes, pos: int, width: int, endian: str) -> int:
    return int.from_bytes(data[pos:pos + width], endian, signed=False)


def _write_int(data: bytes, pos: int, width: int, endian: str, value: int) -> bytes:
    if pos + width > len(data):
        return data
    buf = bytearray(data)
    buf[pos:pos + width] = _to_unsigned(value, width).to_bytes(width, endian)
    return bytes(buf)


def _hash_bytes(data: bytes) -> str:
    return sha1(data).hexdigest()


@dataclass
class ExecutionOutcome:
    """Result of running one input through the simulated target."""

    data: bytes
    coverage: Set[int]
    bitmap_indexes: Set[int]
    is_crash: bool
    exec_time: float
    path_id: str
    coverage_hash: str


@dataclass
class CalibrationResult:
    """Summary of AFL's test-case calibration."""

    outcome: ExecutionOutcome
    stability: float
    varying_paths: int


@dataclass
class ForkServerSimulator:
    """Cheap fork-server model with deterministic startup and fork costs."""

    startup_cost: float = 0.0005
    fork_cost: float = 0.0001

    def __post_init__(self):
        self.started = False
        self.execs = 0
        self.forks = 0

    def run(self, target, data: bytes) -> Tuple[Set[int], bool, float]:
        startup = 0.0
        if not self.started:
            self.started = True
            startup = self.startup_cost
        self.execs += 1
        self.forks += 1
        coverage, is_crash, exec_time = target.execute(data)
        return coverage, is_crash, exec_time + self.fork_cost + startup


class AFLFuzzer:
    """Coverage-guided greybox fuzzer modeled after AFL."""

    def __init__(
        self,
        target,
        seed: int = 42,
        initial_corpus: Optional[Sequence[bytes]] = None,
        user_dictionary: Optional[Sequence[bytes]] = None,
        max_auto_dict_entries: int = 32,
    ):
        self.target = target
        self.rng = np.random.RandomState(seed)
        self.seed = seed
        self.bitmap = CoverageBitmap()
        self.forkserver = ForkServerSimulator()
        self.initial_corpus = list(initial_corpus or [])
        self.user_dictionary = list(dict.fromkeys(user_dictionary or []))
        self.auto_dictionary: List[bytes] = []
        self.max_auto_dict_entries = max_auto_dict_entries

        self.queue: List[TestCase] = []
        self.top_rated: Dict[int, TestCase] = {}
        self.global_edges: Set[int] = set()
        self.unique_paths: Set[str] = set()
        self.crashes: Dict[str, TestCase] = {}
        self.path_counter: Counter[str] = Counter()
        self.execution_order: List[str] = []
        self.total_execs = 0
        self.iteration = 0

        self.edge_to_blocks_map: Dict[int, Tuple[int, int]] = {}
        program = getattr(target, "program", None)
        if program is not None:
            for edge in getattr(program, "edges", []):
                self.edge_to_blocks_map[edge.edge_id] = (edge.src, edge.dst)

        total_edges = getattr(target, "get_total_edges", None)
        self.total_edges = total_edges() if callable(total_edges) else len(self.edge_to_blocks_map)

    def edge_to_blocks(self, edge_id: int) -> Tuple[int, int]:
        if edge_id in self.edge_to_blocks_map:
            return self.edge_to_blocks_map[edge_id]
        return edge_id * 2, edge_id * 2 + 1

    def edge_to_bitmap_index(self, edge_id: int) -> int:
        src, dst = self.edge_to_blocks(edge_id)
        return CoverageBitmap.edge_index(src, dst)

    def coverage_to_bitmap_indexes(self, coverage: Iterable[int]) -> Set[int]:
        return {self.edge_to_bitmap_index(edge_id) for edge_id in coverage}

    def execute_input(self, data: bytes) -> ExecutionOutcome:
        coverage, is_crash, exec_time = self.forkserver.run(self.target, data)
        bitmap_indexes = self.coverage_to_bitmap_indexes(coverage)
        path_id = CoverageBitmap.stable_hash(coverage)
        coverage_hash = CoverageBitmap.stable_hash(bitmap_indexes)
        self.total_execs += 1
        self.path_counter[path_id] += 1
        self.execution_order.append(path_id)
        outcome = ExecutionOutcome(
            data=data,
            coverage=set(coverage),
            bitmap_indexes=bitmap_indexes,
            is_crash=is_crash,
            exec_time=exec_time,
            path_id=path_id,
            coverage_hash=coverage_hash,
        )
        self.on_execution(outcome, None)
        return outcome

    def on_execution(self, outcome: ExecutionOutcome, parent: Optional[TestCase]):
        """Hook for paper-specific fuzzer variants."""

    def on_new_testcase(self, testcase: TestCase, parent: Optional[TestCase]):
        """Hook invoked when a testcase enters the queue."""

    def calibrate(self, data: bytes, runs: int = 3) -> CalibrationResult:
        outcomes = [self.execute_input(data) for _ in range(max(1, runs))]
        base = outcomes[0]
        matching = sum(1 for outcome in outcomes if outcome.path_id == base.path_id)
        stability = 100.0 * matching / len(outcomes)
        varying_paths = len({outcome.path_id for outcome in outcomes})
        return CalibrationResult(base, stability, varying_paths)

    def extract_auto_dictionary(self, data: bytes):
        """Extract simple byte tokens as AFL's auto-dictionary analogue."""
        if len(self.auto_dictionary) >= self.max_auto_dict_entries:
            return

        seen = {token for token in self.auto_dictionary}
        for token_len in range(2, 5):
            for pos in range(0, max(0, len(data) - token_len + 1)):
                token = data[pos:pos + token_len]
                if token in seen:
                    continue
                if all(32 <= byte <= 126 for byte in token) or len(set(token)) == 1:
                    self.auto_dictionary.append(token)
                    seen.add(token)
                    if len(self.auto_dictionary) >= self.max_auto_dict_entries:
                        return

    def trim_testcase(self, testcase: TestCase) -> TestCase:
        """Trim input using powers-of-two deletions while preserving coverage."""
        if testcase.is_crash or len(testcase.data) <= 1:
            return testcase

        target_coverage = set(testcase.coverage)
        target_path = testcase.path_id
        data = testcase.data
        block = 1 << (len(data).bit_length() - 1)

        while block > 0 and len(data) > 1:
            pos = 0
            reduced = False
            while pos + block <= len(data) and len(data) > 1:
                candidate = data[:pos] + data[pos + block:]
                if not candidate:
                    pos += block
                    continue
                outcome = self.execute_input(candidate)
                if outcome.coverage == target_coverage and outcome.path_id == target_path:
                    data = candidate
                    testcase.exec_time = outcome.exec_time
                    testcase.bitmap_indexes = outcome.bitmap_indexes
                    reduced = True
                    continue
                pos += block
            if not reduced:
                block //= 2

        testcase.data = data
        return testcase

    def make_testcase(
        self,
        data: bytes,
        outcome: ExecutionOutcome,
        stability: float,
        depth: int,
        parent: Optional[TestCase] = None,
    ) -> TestCase:
        testcase = TestCase(
            data=data,
            coverage=set(outcome.coverage),
            exec_time=outcome.exec_time,
            is_crash=outcome.is_crash,
            depth=depth,
            creation_time=self.iteration,
            bitmap_indexes=set(outcome.bitmap_indexes),
            stability=stability,
            path_id=outcome.path_id,
            coverage_hash=outcome.coverage_hash,
        )
        testcase.metadata["parent_fuzz_count"] = float(parent.fuzz_count) if parent else 0.0
        return testcase

    def compute_perf_score(self, testcase: TestCase) -> float:
        """Compute AFL's constant-schedule performance score analogue."""
        if not self.queue:
            testcase.perf_score = 100.0
            testcase.energy = 100
            return testcase.perf_score

        avg_exec = sum(tc.exec_time for tc in self.queue) / len(self.queue)
        avg_cov = sum(len(tc.coverage) for tc in self.queue) / len(self.queue)

        speed_factor = avg_exec / max(testcase.exec_time, 1e-9)
        cov_factor = len(testcase.coverage) / max(avg_cov, 1.0)
        depth_factor = 1.0 + min(testcase.depth, 8) * 0.1
        stability_factor = testcase.stability / 100.0

        score = 100.0 * speed_factor * cov_factor * depth_factor * stability_factor
        if testcase.is_favored:
            score *= 1.25
        testcase.perf_score = max(1.0, min(score, 1000.0))
        testcase.energy = max(1, int(round(testcase.perf_score)))
        return testcase.perf_score

    def cull_corpus(self):
        """Greedy set cover favoring small and fast testcases per edge."""
        if not self.queue:
            return

        coverage_map: Dict[int, List[TestCase]] = defaultdict(list)
        for testcase in self.queue:
            testcase.is_favored = False
            testcase.unique_edges = set()
            for edge in testcase.coverage:
                coverage_map[edge].append(testcase)

        self.top_rated.clear()
        for edge, cases in coverage_map.items():
            self.top_rated[edge] = min(
                cases,
                key=lambda tc: (tc.size, tc.exec_time, -len(tc.coverage), tc.creation_time),
            )

        uncovered = set(self.global_edges)
        while uncovered:
            candidates = {self.top_rated[edge] for edge in uncovered if edge in self.top_rated}
            if not candidates:
                break
            best = max(
                candidates,
                key=lambda tc: (
                    len(tc.coverage & uncovered),
                    -tc.size,
                    -tc.exec_time,
                    tc.creation_time,
                ),
            )
            best.is_favored = True
            uncovered -= best.coverage

        edge_counts: Counter[int] = Counter()
        for testcase in self.queue:
            for edge in testcase.coverage:
                edge_counts[edge] += 1
        for testcase in self.queue:
            testcase.unique_edges = {edge for edge in testcase.coverage if edge_counts[edge] == 1}
            self.compute_perf_score(testcase)

    def _register_interesting_testcase(
        self,
        data: bytes,
        outcome: ExecutionOutcome,
        depth: int,
        parent: Optional[TestCase],
        force: bool,
        trim: bool,
    ) -> Optional[TestCase]:
        new_edges = outcome.coverage - self.global_edges
        new_path = outcome.path_id not in self.unique_paths
        new_crash = outcome.is_crash and outcome.coverage_hash not in self.crashes

        if not force and not (new_edges or new_path or new_crash):
            return None

        calibration = self.calibrate(data)
        testcase = self.make_testcase(
            data=data,
            outcome=calibration.outcome,
            stability=calibration.stability,
            depth=depth,
            parent=parent,
        )
        if trim:
            testcase = self.trim_testcase(testcase)

        self.global_edges.update(testcase.coverage)
        self.unique_paths.add(testcase.path_id)
        self.bitmap.record_indexes(sorted(testcase.bitmap_indexes))
        self.extract_auto_dictionary(testcase.data)

        if testcase.is_crash:
            self.crashes.setdefault(testcase.coverage_hash, testcase)

        self.queue.append(testcase)
        self.cull_corpus()
        self.on_new_testcase(testcase, parent)
        return testcase

    def add_seed(
        self,
        data: bytes,
        depth: int = 0,
        parent: Optional[TestCase] = None,
        force: bool = False,
        trim: bool = True,
    ) -> Optional[TestCase]:
        outcome = self.execute_input(data)
        return self._register_interesting_testcase(
            data=data,
            outcome=outcome,
            depth=depth,
            parent=parent,
            force=force,
            trim=trim,
        )

    def choose_seed(self) -> Optional[TestCase]:
        if not self.queue:
            return None

        candidates = [testcase for testcase in self.queue if not testcase.is_crash] or list(self.queue)
        favored = [testcase for testcase in candidates if testcase.is_favored]
        if favored and self.rng.rand() < 0.75:
            pool = favored
        else:
            pool = candidates

        pool = sorted(pool, key=self.seed_priority_key)
        return pool[int(self.rng.randint(0, len(pool)))]

    def seed_priority_key(self, testcase: TestCase) -> Tuple[float, ...]:
        return (
            testcase.was_fuzzed,
            testcase.times_chosen,
            -len(testcase.unique_edges),
            testcase.creation_time,
            testcase.size,
        )

    def should_skip_seed(self, testcase: TestCase) -> bool:
        return False

    def compute_energy(self, testcase: TestCase) -> int:
        self.compute_perf_score(testcase)
        return testcase.energy

    def iter_bitflip_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        self.extract_auto_dictionary(data)
        max_bits = len(data) * 8
        for width in (1, 2, 4):
            for pos in range(0, max(0, max_bits - width + 1)):
                yield f"bitflip_{width}", bit_flip(data, pos, width)

    def iter_byteflip_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        for width in (1, 2, 4):
            if len(data) < width:
                continue
            for pos in range(0, len(data) - width + 1):
                yield f"byteflip_{width * 8}", byte_flip(data, pos, width)

    def iter_arith_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        for width in (1, 2, 4):
            if len(data) < width:
                continue
            endians = ("little", "big") if width > 1 else ("little",)
            for pos in range(0, len(data) - width + 1):
                for endian in endians:
                    base_value = _read_int(data, pos, width, endian)
                    for delta in range(1, 36):
                        yield f"arith_add_{width * 8}_{endian}", _write_int(
                            data,
                            pos,
                            width,
                            endian,
                            base_value + delta,
                        )
                        yield f"arith_sub_{width * 8}_{endian}", _write_int(
                            data,
                            pos,
                            width,
                            endian,
                            base_value - delta,
                        )

    def iter_interesting_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        values_by_width = {
            1: INTERESTING_8,
            2: INTERESTING_16,
            4: INTERESTING_32,
        }
        for width, values in values_by_width.items():
            if len(data) < width:
                continue
            endians = ("little", "big") if width > 1 else ("little",)
            for pos in range(0, len(data) - width + 1):
                for endian in endians:
                    for value in values:
                        yield f"interesting_{width * 8}_{endian}", _write_int(
                            data,
                            pos,
                            width,
                            endian,
                            value,
                        )

    def iter_dictionary_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        dictionary = list(dict.fromkeys(self.user_dictionary + self.auto_dictionary))
        for token in dictionary:
            if not token:
                continue
            for pos in range(0, len(data) + 1):
                yield "dict_insert", insert_bytes(data, pos, token)
            if len(token) <= len(data):
                for pos in range(0, len(data) - len(token) + 1):
                    yield "dict_overwrite", data[:pos] + token + data[pos + len(token):]

    def iter_deterministic_mutations(self, data: bytes) -> Iterator[Tuple[str, bytes]]:
        yielded: Set[str] = set()
        for iterator in (
            self.iter_bitflip_mutations(data),
            self.iter_byteflip_mutations(data),
            self.iter_arith_mutations(data),
            self.iter_interesting_mutations(data),
            self.iter_dictionary_mutations(data),
        ):
            for stage, mutated in iterator:
                if mutated == data:
                    continue
                digest = _hash_bytes(mutated)
                if digest in yielded:
                    continue
                yielded.add(digest)
                yield stage, mutated

    def _apply_random_mutation(self, data: bytes) -> bytes:
        if not data:
            data = b"\x00"
        op = int(self.rng.randint(0, 10))
        pos = int(self.rng.randint(0, max(1, len(data))))

        if op == 0:
            bit_pos = int(self.rng.randint(0, max(1, len(data) * 8)))
            width = int(2 ** self.rng.randint(0, 3))
            return bit_flip(data, bit_pos, width)
        if op == 1:
            width = min(len(data), int(2 ** self.rng.randint(0, 3)))
            return byte_flip(data, min(pos, max(0, len(data) - width)), width)
        if op == 2:
            return arith_add(data, pos, int(self.rng.randint(1, 36)))
        if op == 3:
            return arith_sub(data, pos, int(self.rng.randint(1, 36)))
        if op == 4:
            width = min(len(data), int(2 ** self.rng.randint(0, 3)))
            if width not in (1, 2, 4):
                width = 1
            endian = "little" if width == 1 or self.rng.rand() < 0.5 else "big"
            values = {1: INTERESTING_8, 2: INTERESTING_16, 4: INTERESTING_32}[width]
            value = values[int(self.rng.randint(0, len(values)))]
            return _write_int(data, min(pos, max(0, len(data) - width)), width, endian, value)
        if op == 5:
            return random_byte(data, pos, self.rng)
        if op == 6 and len(data) > 1:
            length = int(self.rng.randint(1, min(len(data), 4) + 1))
            return delete_bytes(data, pos, length)
