"""AFLFast power schedules and Markov-chain helpers."""

from __future__ import annotations

from collections import Counter, defaultdict
from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Optional, Sequence, Set, Tuple

from fuzzsim.bitmap import CoverageBitmap


EXPLOIT = "EXPLOIT"
EXPLORE = "EXPLORE"
COE = "COE"
FAST = "FAST"
LINEAR = "LINEAR"
QUAD = "QUAD"
LIN = LINEAR

ALL_SCHEDULES = (FAST, COE, EXPLORE, EXPLOIT, LINEAR, QUAD)


@dataclass
class PathFrequencyTracker:
    """Track AFLFast's Markov-chain state frequencies and transitions."""

    path_frequencies: Counter = field(default_factory=Counter)
    selection_counts: Counter = field(default_factory=Counter)
    transitions: Counter = field(default_factory=Counter)
    states: Dict[str, Set[int]] = field(default_factory=dict)

    @staticmethod
    def identify_state(coverage: Iterable[int]) -> str:
        return CoverageBitmap.stable_hash(set(coverage))

    def record_execution(
        self,
        path_id: str,
        coverage: Optional[Iterable[int]] = None,
        parent_path: Optional[str] = None,
    ):
        self.path_frequencies[path_id] += 1
        if coverage is not None:
            self.states.setdefault(path_id, set(coverage))
        if parent_path is not None:
            self.transitions[(parent_path, path_id)] += 1

    def record_selection(self, path_id: str):
        self.selection_counts[path_id] += 1

    def get_frequency(self, path_id: str) -> int:
        return int(self.path_frequencies.get(path_id, 0))

    def get_selection_count(self, path_id: str) -> int:
        return int(self.selection_counts.get(path_id, 0))

    def get_transition_count(self, src: str, dst: str) -> int:
        return int(self.transitions.get((src, dst), 0))

    def transition_probabilities(self) -> Dict[str, Dict[str, float]]:
        outgoing_totals: Counter = Counter()
        for (src, _), count in self.transitions.items():
            outgoing_totals[src] += count

        matrix: Dict[str, Dict[str, float]] = defaultdict(dict)
        for (src, dst), count in self.transitions.items():
            total = float(outgoing_totals[src])
            matrix[src][dst] = count / total if total else 0.0
        return dict(matrix)

    def rare_paths(self, percentile: float = 0.2) -> Set[str]:
        if not self.path_frequencies:
            return set()
        percentile = min(max(percentile, 0.0), 1.0)
        counts = sorted(self.path_frequencies.values())
        index = int(round((len(counts) - 1) * percentile))
        threshold = counts[index]
        return {path_id for path_id, count in self.path_frequencies.items() if count <= threshold}


@dataclass
class EnergyComputer:
    """Compute AFLFast schedule energies and analyze their distribution."""

    alpha: float = 100.0
    beta: float = 1.0
    mu: float = 5.0
    max_energy: float = 512.0

    def compute(
        self,
        schedule: str,
        frequency: float,
        selection_count: float,
        beta: Optional[float] = None,
    ) -> float:
        schedule = schedule.upper()
        beta_value = max(beta if beta is not None else self.beta, 1.0)
        f = max(float(frequency), 1.0)
        s = max(float(selection_count), 1.0)
        base = self.alpha / beta_value

        if schedule == EXPLOIT:
            return min(self.alpha, self.max_energy)
        if schedule == EXPLORE:
            return min(base, self.max_energy)
        if schedule == COE:
            if f > self.mu:
                return 0.0
            return min(base * (2.0 ** s), self.max_energy)
        if schedule == FAST:
            return min(base * (2.0 ** s) / f, self.max_energy)
        if schedule == LINEAR:
            return min(base * s / f, self.max_energy)
        if schedule == QUAD:
            return min(base * (s ** 2) / f, self.max_energy)
        raise ValueError(f"unknown AFLFast schedule: {schedule}")

    def compute_many(
        self,
        schedule: str,
        frequencies: Sequence[float],
        selection_counts: Sequence[float],
        beta: Optional[float] = None,
    ) -> List[float]:
        return [
            self.compute(schedule, frequency, selection_count, beta=beta)
            for frequency, selection_count in zip(frequencies, selection_counts)
        ]

    @staticmethod
    def gini_coefficient(values: Sequence[float]) -> float:
        if not values:
            return 0.0
        ordered = sorted(float(value) for value in values)
        total = sum(ordered)
        if total == 0.0:
            return 0.0
        n = len(ordered)
        weighted_sum = sum((index + 1) * value for index, value in enumerate(ordered))
        return (2.0 * weighted_sum) / (n * total) - (n + 1.0) / n

    def summarize(self, schedule: str, tracker: PathFrequencyTracker) -> Dict[str, float]:
        path_ids = sorted(tracker.path_frequencies)
        beta = max(len(path_ids), 1)
        energies = [
            self.compute(
                schedule,
                tracker.get_frequency(path_id),
                tracker.get_selection_count(path_id),
                beta=beta,
            )
            for path_id in path_ids
        ]
        if not energies:
            return {"mean": 0.0, "gini": 0.0}
        mean = sum(energies) / len(energies)
        return {
            "mean": mean,
            "gini": self.gini_coefficient(energies),
        }

