"""AFLGo distance computation helpers."""

from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import dataclass, field
from math import inf
from typing import Dict, Iterable, List, Mapping, Optional, Sequence, Set, Tuple


def harmonic_mean(values: Sequence[float]) -> float:
    finite = [value for value in values if value != inf]
    if not finite:
        return inf
    if any(value == 0.0 for value in finite):
        return 0.0
    return len(finite) / sum(1.0 / value for value in finite)


@dataclass
class CallGraph:
    """Directed call graph with reverse-BFS distance computation."""

    functions: Set[str] = field(default_factory=set)
    edges: Dict[str, Set[str]] = field(default_factory=lambda: defaultdict(set))
    reverse_edges: Dict[str, Set[str]] = field(default_factory=lambda: defaultdict(set))

    def add_function(self, name: str):
        self.functions.add(name)
        self.edges.setdefault(name, set())
        self.reverse_edges.setdefault(name, set())

    def add_edge(self, caller: str, callee: str):
        self.add_function(caller)
        self.add_function(callee)
        self.edges[caller].add(callee)
        self.reverse_edges[callee].add(caller)

    def reverse_bfs(self, target_functions: Iterable[str]) -> Dict[str, float]:
        distances = {name: inf for name in self.functions}
        queue = deque()
        for function_name in target_functions:
            self.add_function(function_name)
            distances[function_name] = 0.0
            queue.append(function_name)

        while queue:
            callee = queue.popleft()
            for caller in self.reverse_edges.get(callee, set()):
                new_distance = distances[callee] + 1.0
                if new_distance < distances[caller]:
                    distances[caller] = new_distance
                    queue.append(caller)
        return distances


@dataclass
class CFGDistance:
    """Reverse shortest-path distances over a basic-block graph."""

    blocks: Set[int] = field(default_factory=set)
    adjacency: Dict[int, Set[int]] = field(default_factory=lambda: defaultdict(set))
    reverse_adjacency: Dict[int, Set[int]] = field(default_factory=lambda: defaultdict(set))

    def add_edge(self, src: int, dst: int):
        self.blocks.add(src)
        self.blocks.add(dst)
        self.adjacency[src].add(dst)
        self.reverse_adjacency[dst].add(src)

    def reverse_shortest_paths(self, target_blocks: Iterable[int]) -> Dict[int, float]:
        distances = {block: inf for block in self.blocks}
        queue = deque()
        for target_block in target_blocks:
            self.blocks.add(target_block)
            distances[target_block] = 0.0
            queue.append(target_block)

        while queue:
            node = queue.popleft()
            for predecessor in self.reverse_adjacency.get(node, set()):
                new_distance = distances[node] + 1.0
                if new_distance < distances[predecessor]:
                    distances[predecessor] = new_distance
                    queue.append(predecessor)
        return distances


@dataclass
class DistanceComputer:
    """Compute AFLGo distances from call-graph and CFG data."""

    call_graph: CallGraph
    cfg_distance: CFGDistance
    block_to_function: Dict[int, str]
    edge_to_blocks: Dict[int, Tuple[int, int]] = field(default_factory=dict)

    function_distances: Dict[str, float] = field(default_factory=dict)
    block_distances: Dict[int, float] = field(default_factory=dict)
    normalized_block_distances: Dict[int, float] = field(default_factory=dict)

    @classmethod
    def from_program(
        cls,
        program,
        block_to_function: Mapping[int, str],
        call_edges: Iterable[Tuple[str, str]],
    ) -> "DistanceComputer":
        call_graph = CallGraph()
        for caller, callee in call_edges:
            call_graph.add_edge(caller, callee)

        cfg = CFGDistance()
        edge_to_blocks: Dict[int, Tuple[int, int]] = {}
        for edge in getattr(program, "edges", []):
            cfg.add_edge(edge.src, edge.dst)
            edge_to_blocks[edge.edge_id] = (edge.src, edge.dst)

        for block_id, function_name in block_to_function.items():
            call_graph.add_function(function_name)
            cfg.blocks.add(block_id)

        return cls(
            call_graph=call_graph,
            cfg_distance=cfg,
            block_to_function=dict(block_to_function),
            edge_to_blocks=edge_to_blocks,
        )

    @staticmethod
    def combine_distances(cfg_distance: float, function_distance: float) -> float:
        if cfg_distance == inf and function_distance == inf:
            return inf
        if cfg_distance == inf:
            return function_distance
        if function_distance == inf:
            return cfg_distance
        if function_distance == 0.0:
            return cfg_distance
        return max(0.0, harmonic_mean([cfg_distance + 1.0, function_distance + 1.0]) - 1.0)

    @staticmethod
    def normalize(distances: Mapping[int, float]) -> Dict[int, float]:
        finite_values = [distance for distance in distances.values() if distance != inf]
        if not finite_values:
            return {block: 1.0 for block in distances}
        min_distance = min(finite_values)
        max_distance = max(finite_values)
        if max_distance == min_distance:
            return {block: (1.0 if distance == inf else 0.0) for block, distance in distances.items()}

        normalized = {}
        for block, distance in distances.items():
            if distance == inf:
                normalized[block] = 1.0
            else:
                normalized[block] = (distance - min_distance) / (max_distance - min_distance)
        return normalized

    def compute(
        self,
        target_blocks: Sequence[int],
        target_functions: Optional[Sequence[str]] = None,
    ) -> Dict[int, float]:
        if target_functions is None:
            target_functions = {
                self.block_to_function[block]
                for block in target_blocks
                if block in self.block_to_function
            }

        self.function_distances = self.call_graph.reverse_bfs(target_functions)
        cfg_only = self.cfg_distance.reverse_shortest_paths(target_blocks)

        all_blocks = set(self.cfg_distance.blocks) | set(self.block_to_function)
        self.block_distances = {}
        for block in all_blocks:
            function_name = self.block_to_function.get(block)
            function_distance = self.function_distances.get(function_name, inf)
            self.block_distances[block] = self.combine_distances(
                cfg_distance=cfg_only.get(block, inf),
                function_distance=function_distance,
            )

        self.normalized_block_distances = self.normalize(self.block_distances)
        return self.normalized_block_distances

    def seed_distance(self, coverage: Iterable[int], normalized: bool = True) -> float:
        if not self.block_distances:
            raise RuntimeError("compute() must be called before seed_distance()")

        distance_map = self.normalized_block_distances if normalized else self.block_distances
        best = inf
        for edge_id in coverage:
            src, dst = self.edge_to_blocks.get(edge_id, (None, None))
            for block in (src, dst):
                if block is None:
                    continue
                best = min(best, distance_map.get(block, inf))
        return 1.0 if best == inf and normalized else best

    @staticmethod
    def accuracy(actual: Mapping[int, float], expected: Mapping[int, float], tolerance: float = 1e-9) -> float:
        if not expected:
            return 100.0
        matched = 0
        for block, expected_distance in expected.items():
            actual_distance = actual.get(block, inf)
            if actual_distance == expected_distance:
                matched += 1
                continue
            if actual_distance != inf and expected_distance != inf and abs(actual_distance - expected_distance) <= tolerance:
                matched += 1
        return 100.0 * matched / len(expected)

