"""AFLGo-style simulated annealing and directed seed prioritization."""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Dict, Iterable, List, Sequence, Tuple

from fuzzsim.aflgo_distance import DistanceComputer
from fuzzsim.seed import TestCase


EXPLORATION = "exploration"
TRANSITION = "transition"
EXPLOITATION = "exploitation"


@dataclass
class SimulatedAnnealing:
    """Cooling schedules used by AFLGo."""

    initial_temperature: float = 1.0
    alpha: float = 0.85
    total_steps: int = 1000
    K: float = 1.0
    schedule: str = "exponential"
    adaptive_alpha: float = 0.85
    best_progress: float = 0.0

    def temperature(self, step: int, progress: float = 0.0) -> float:
        step = max(step, 0)
        tx = max(self.total_steps, 1)
        ratio = step / (tx * self.K if self.K else tx)
        schedule = self.schedule.lower()
        t0 = self.initial_temperature

        if schedule == "exponential":
            return max(0.0, t0 * (self.alpha ** ratio))
        if schedule == "linear":
            return max(0.0, t0 * (1.0 - step / tx))
        if schedule == "logarithmic":
            scaled = step / tx * self.K
            return max(0.0, t0 / (1.0 + math.log1p(scaled)))
        if schedule == "adaptive":
            delta = progress - self.best_progress
            if delta > 0:
                self.adaptive_alpha = max(0.60, self.adaptive_alpha * 0.98)
                self.best_progress = progress
            else:
                self.adaptive_alpha = min(0.99, self.adaptive_alpha * 1.01)
            return max(0.0, t0 * (self.adaptive_alpha ** ratio))
        raise ValueError(f"unknown cooling schedule: {self.schedule}")

    def phase(self, step: int, progress: float = 0.0) -> str:
        temperature = self.temperature(step, progress)
        if temperature >= 0.7:
            return EXPLORATION
        if temperature >= 0.3:
            return TRANSITION
        return EXPLOITATION

    @staticmethod
    def assign_energy(base: float, normalized_distance: float, temperature: float) -> float:
        distance = min(max(normalized_distance, 0.0), 1.0)
        temp = min(max(temperature, 0.0), 1.0)
        return base * (((1.0 - distance) * (1.0 - temp)) + 0.5 * temp)

    @staticmethod
    def should_skip(normalized_distance: float, temperature: float) -> bool:
        return temperature < 0.3 and normalized_distance > 0.9


@dataclass
class AFLGoPolicy:
    """Distance-aware prioritization policy for directed fuzzing."""

    distance_computer: DistanceComputer
    annealing: SimulatedAnnealing
    base_energy: float = 100.0

    def seed_distance(self, testcase: TestCase) -> float:
        return self.distance_computer.seed_distance(testcase.coverage, normalized=True)

    def testcase_energy(self, testcase: TestCase, step: int, progress: float = 0.0) -> float:
        temperature = self.annealing.temperature(step, progress)
        distance = self.seed_distance(testcase)
        return self.annealing.assign_energy(self.base_energy, distance, temperature)

    def should_skip(self, testcase: TestCase, step: int, progress: float = 0.0) -> bool:
        temperature = self.annealing.temperature(step, progress)
        distance = self.seed_distance(testcase)
        return self.annealing.should_skip(distance, temperature)

    def prioritize(
        self,
        testcases: Sequence[TestCase],
        step: int,
        progress: float = 0.0,
    ) -> List[TestCase]:
        temperature = self.annealing.temperature(step, progress)
        ranked = sorted(
            testcases,
            key=lambda testcase: (
                self.annealing.should_skip(self.seed_distance(testcase), temperature),
                self.seed_distance(testcase),
                -self.annealing.assign_energy(
                    self.base_energy,
                    self.seed_distance(testcase),
                    temperature,
                ),
                testcase.creation_time,
            ),
        )
        return ranked

