"""Rare-branch tracking and targeting for FairFuzz."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass, field
from typing import Dict, Iterable, Mapping, Optional, Sequence, Set


@dataclass
class RareBranchTracker:
    """Track per-edge seed frequencies and identify rare branches."""

    seed_coverages: Dict[str, Set[int]] = field(default_factory=dict)
    edge_counts: Counter = field(default_factory=Counter)

    def update(self, seed_id: str, coverage: Iterable[int]):
        coverage_set = set(coverage)
        previous = self.seed_coverages.get(seed_id)
        if previous is not None:
            for edge in previous:
                self.edge_counts[edge] -= 1
                if self.edge_counts[edge] <= 0:
                    del self.edge_counts[edge]
        self.seed_coverages[seed_id] = coverage_set
        for edge in coverage_set:
            self.edge_counts[edge] += 1

    def threshold(self, fixed_cutoff: Optional[int] = None, percentile: Optional[float] = None) -> int:
        if not self.edge_counts:
            return 0
        if fixed_cutoff is not None:
            return max(int(fixed_cutoff), 0)
        if percentile is None:
            percentile = 0.25
        percentile = min(max(percentile, 0.0), 1.0)
        counts = sorted(self.edge_counts.values())
        index = int(round((len(counts) - 1) * percentile))
        return counts[index]

    def rare_edges(
        self,
        fixed_cutoff: Optional[int] = None,
        percentile: Optional[float] = None,
        threshold: Optional[int] = None,
    ) -> Set[int]:
        limit = threshold
        if limit is None:
            limit = self.threshold(fixed_cutoff=fixed_cutoff, percentile=percentile)
        return {edge for edge, count in self.edge_counts.items() if count <= limit}

    def rarity_scores(self) -> Dict[int, float]:
        if not self.edge_counts:
            return {}
        counts = list(self.edge_counts.values())
        min_count = min(counts)
        max_count = max(counts)
        if min_count == max_count:
            return {edge: 1.0 for edge in self.edge_counts}

        scores = {}
        for edge, count in self.edge_counts.items():
            scores[edge] = (max_count - count) / (max_count - min_count)
        return scores

    def select_target_branch(
        self,
        coverage: Iterable[int],
        fixed_cutoff: Optional[int] = None,
        percentile: Optional[float] = None,
        threshold: Optional[int] = None,
    ) -> Optional[int]:
        rare = self.rare_edges(
            fixed_cutoff=fixed_cutoff,
            percentile=percentile,
            threshold=threshold,
        )
        candidates = list(set(coverage) & rare)
        if not candidates:
            return None
        scores = self.rarity_scores()
        return min(
            candidates,
            key=lambda edge: (
                self.edge_counts.get(edge, 0),
                -scores.get(edge, 0.0),
                edge,
            ),
        )

    def stats(self) -> Dict[str, float]:
        rare = self.rare_edges(percentile=0.25)
        return {
            "tracked_seeds": float(len(self.seed_coverages)),
            "tracked_edges": float(len(self.edge_counts)),
            "rare_edges": float(len(rare)),
        }

