"""Probe-based influence detection and masked mutations for FairFuzz."""

from __future__ import annotations

from dataclasses import dataclass, field
from hashlib import sha1
from typing import Dict, Iterable, List, Optional, Sequence, Set, Tuple

import numpy as np

from fuzzsim.afl_fuzzer import AFLFuzzer
from fuzzsim.fairfuzz_rare import RareBranchTracker
from fuzzsim.mutation import INTERESTING_8, arith_add, arith_sub, byte_flip, random_byte
from fuzzsim.seed import TestCase


@dataclass
class InfluenceDetector:
    """Infer byte-to-branch influence by differential probing."""

    target: object
    probes: int = 5
    destruction_threshold: float = 0.6
    seed: int = 42
    cache: Dict[Tuple[str, int], List[bool]] = field(default_factory=dict)

    def __post_init__(self):
        self.rng = np.random.RandomState(self.seed)

    @staticmethod
    def cache_key(data: bytes, target_branch: int) -> Tuple[str, int]:
        return sha1(data).hexdigest(), int(target_branch)

    def detect_influential_bytes(self, data: bytes, target_branch: int, fast: bool = True) -> Set[int]:
        coverage, _, _ = self.target.execute(data)
        if target_branch not in coverage:
            return set()

        influential: Set[int] = set()
        threshold_count = self.destruction_threshold * self.probes
        for pos in range(len(data)):
            destroyed = 0
            for attempt in range(self.probes):
                replacement = data[pos]
                while replacement == data[pos]:
                    replacement = int(self.rng.randint(0, 256))
                mutated = data[:pos] + bytes([replacement]) + data[pos + 1:]
                mutated_coverage, _, _ = self.target.execute(mutated)
                if target_branch not in mutated_coverage:
                    destroyed += 1

                if fast:
                    remaining = self.probes - attempt - 1
                    if destroyed > threshold_count:
                        break
                    if destroyed + remaining <= threshold_count:
                        break
            if destroyed / self.probes > self.destruction_threshold:
                influential.add(pos)
        return influential

    def mutation_mask(self, data: bytes, target_branch: int, fast: bool = True) -> List[bool]:
        key = self.cache_key(data, target_branch)
        if key in self.cache:
            return list(self.cache[key])

        influential = self.detect_influential_bytes(data, target_branch, fast=fast)
        mask = [index not in influential for index in range(len(data))]
        self.cache[key] = list(mask)
        return mask


def targeted_havoc(
    data: bytes,
    mutation_mask: Sequence[bool],
    rng: np.random.RandomState,
    num_mutations: Optional[int] = None,
) -> bytes:
    """Apply havoc-like operations while preserving masked positions."""
    safe_positions = [index for index, can_mutate in enumerate(mutation_mask) if can_mutate]
    if not safe_positions:
        return data

    if num_mutations is None:
        num_mutations = 2 ** int(rng.randint(1, 5))

    result = data
    for _ in range(max(1, num_mutations)):
        safe_positions = [index for index, can_mutate in enumerate(mutation_mask[: len(result)]) if can_mutate]
        if not safe_positions:
            break
        pos = safe_positions[int(rng.randint(0, len(safe_positions)))]
        op = int(rng.randint(0, 6))
        if op == 0:
            result = random_byte(result, pos, rng)
        elif op == 1:
            result = byte_flip(result, pos, 1)
        elif op == 2:
            result = arith_add(result, pos, int(rng.randint(1, 36)))
        elif op == 3:
            result = arith_sub(result, pos, int(rng.randint(1, 36)))
        elif op == 4:
            buf = bytearray(result)
            buf[pos] = INTERESTING_8[int(rng.randint(0, len(INTERESTING_8)))] & 0xFF
            result = bytes(buf)
        elif len(safe_positions) > 1:
            other = pos
            while other == pos:
                other = safe_positions[int(rng.randint(0, len(safe_positions)))]
            buf = bytearray(result)
            buf[pos], buf[other] = buf[other], buf[pos]
            result = bytes(buf)
    return result


class FairFuzzFuzzer(AFLFuzzer):
    """AFL variant that prioritizes rare branches and preserves their input bytes."""

    def __init__(
        self,
        target,
        seed: int = 42,
        rarity_percentile: float = 0.25,
        fixed_cutoff: Optional[int] = None,
        initial_corpus: Optional[Sequence[bytes]] = None,
        user_dictionary: Optional[Sequence[bytes]] = None,
    ):
        super().__init__(
            target=target,
            seed=seed,
            initial_corpus=initial_corpus,
            user_dictionary=user_dictionary,
        )
        self.rarity_percentile = rarity_percentile
        self.fixed_cutoff = fixed_cutoff
        self.rare_tracker = RareBranchTracker()
        self.influence_detector = InfluenceDetector(target=target, seed=seed)

    def testcase_id(self, testcase: TestCase) -> str:
        return f"{testcase.path_id}:{testcase.creation_time}:{testcase.size}"

    def on_new_testcase(self, testcase: TestCase, parent: Optional[TestCase]):
        self.rare_tracker.update(self.testcase_id(testcase), testcase.coverage)

    def choose_target_branch(self, testcase: TestCase) -> Optional[int]:
        return self.rare_tracker.select_target_branch(
            testcase.coverage,
            fixed_cutoff=self.fixed_cutoff,
            percentile=self.rarity_percentile,
        )

    def run_targeted_havoc(self, testcase: TestCase, cycles: int) -> int:
        target_branch = self.choose_target_branch(testcase)
        if target_branch is None:
            return self.run_havoc_stage(testcase, cycles=cycles)

        mask = self.influence_detector.mutation_mask(testcase.data, target_branch, fast=True)
        for _ in range(max(1, cycles)):
            mutated = targeted_havoc(testcase.data, mask, self.rng)
            self.process_mutation(testcase, mutated, "havoc_targeted")
        return cycles

    def fuzz_one(self, testcase: TestCase):
        testcase.times_chosen += 1
        testcase.fuzz_count += 1
        if not testcase.was_fuzzed:
            self.run_deterministic_stages(testcase)
        cycles = max(1, self.compute_energy(testcase) // 8)
        self.run_targeted_havoc(testcase, cycles=cycles)
        self.run_splice_stage(testcase, cycles=2)
        testcase.was_fuzzed = True
        self.cull_corpus()

