"""AFL++-style custom mutator API and registry."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np


class CustomMutator:
    """Base class matching AFL++'s custom mutator callbacks."""

    name = "custom"

    def __init__(self, seed: int = 42):
        self.seed = seed
        self.rng = np.random.RandomState(seed)
        self.state = self.init(seed)

    def init(self, seed: int = 42):
        return {"seed": seed}

    def fuzz(self, buf: bytes, add_buf: bytes = b"") -> bytes:
        return buf + add_buf

    def fuzz_count(self, buf: bytes) -> int:
        return 1

    def havoc_mutation(self, buf: bytes, max_size: int) -> bytes:
        return buf[:max_size]

    def havoc_mutation_probability(self) -> float:
        return 0.10

    def post_process(self, buf: bytes) -> bytes:
        return buf

    def trim(self, buf: bytes) -> bytes:
        return buf

    def describe(self) -> str:
        return self.__class__.__name__

    def queue_new_entry(self, buf: bytes, coverage: Iterable[int]) -> bool:
        return False


@dataclass
class MutatorRegistry:
    """Register mutators and select them using dynamic weighted sampling."""

    mutators: Dict[str, CustomMutator] = field(default_factory=dict)
    weights: Dict[str, float] = field(default_factory=dict)

    def register(self, mutator: CustomMutator, weight: float = 1.0):
        self.mutators[mutator.describe()] = mutator
        self.weights[mutator.describe()] = max(float(weight), 0.1)

    def unregister(self, mutator_name: str):
        self.mutators.pop(mutator_name, None)
        self.weights.pop(mutator_name, None)

    def select(self, rng: Optional[np.random.RandomState] = None) -> CustomMutator:
        if not self.mutators:
            raise RuntimeError("no mutators registered")
        rng = rng or np.random.RandomState(42)
        names = sorted(self.mutators)
        weights = np.array([self.weights[name] for name in names], dtype=float)
        probabilities = weights / weights.sum()
        index = int(rng.choice(len(names), p=probabilities))
        return self.mutators[names[index]]

    def adjust_weight(self, mutator_name: str, success: bool):
        weight = self.weights.get(mutator_name)
        if weight is None:
            return
        if success:
            weight *= 1.1
        else:
            weight *= 0.99
        self.weights[mutator_name] = max(weight, 0.1)

    def distribution(self) -> Dict[str, float]:
        if not self.weights:
            return {}
        total = sum(self.weights.values())
        return {name: weight / total for name, weight in self.weights.items()}


class GrammarMutator(CustomMutator):
    """Simple grammar-aware mutator with token templates."""

    name = "grammar"

    def __init__(
        self,
        seed: int = 42,
        templates: Optional[Sequence[bytes]] = None,
        tokens: Optional[Sequence[bytes]] = None,
    ):
        self.templates = list(
            templates
            or (
                b"HDR %BODY% END",
                b"CMD(%BODY%)",
                b"<root>%BODY%</root>",
            )
        )
        self.tokens = list(tokens or (b"foo", b"bar", b"MZ", b"BODY", b"ARG"))
        super().__init__(seed=seed)

    def fuzz(self, buf: bytes, add_buf: bytes = b"") -> bytes:
        template = self.templates[int(self.rng.randint(0, len(self.templates)))]
        body = add_buf or buf or self.tokens[int(self.rng.randint(0, len(self.tokens)))]
        extra = self.tokens[int(self.rng.randint(0, len(self.tokens)))]
        result = template.replace(b"%BODY%", body).replace(b"%EXTRA%", extra)
        return result

    def fuzz_count(self, buf: bytes) -> int:
        return max(1, min(len(self.tokens), 4))

    def havoc_mutation(self, buf: bytes, max_size: int) -> bytes:
        tokens = re.split(rb"[\s<>()/]+", buf)
        tokens = [token for token in tokens if token]
        if not tokens:
            tokens = [self.tokens[int(self.rng.randint(0, len(self.tokens)))]]
        op = int(self.rng.randint(0, 3))
        if op == 0:
            index = int(self.rng.randint(0, len(tokens)))
            tokens[index] = self.tokens[int(self.rng.randint(0, len(self.tokens)))]
        elif op == 1:
            index = int(self.rng.randint(0, len(tokens) + 1))
            tokens.insert(index, self.tokens[int(self.rng.randint(0, len(self.tokens)))])
        elif len(tokens) > 1:
            del tokens[int(self.rng.randint(0, len(tokens)))]
        mutated = b" ".join(tokens)
        return mutated[:max_size]

    def havoc_mutation_probability(self) -> float:
        return 0.35

    def post_process(self, buf: bytes) -> bytes:
        return re.sub(rb"\s+", b" ", buf).strip() or b"HDR END"

    def trim(self, buf: bytes) -> bytes:
        tokens = re.split(rb"[\s<>()/]+", buf)
        tokens = [token for token in tokens if token]
        if len(tokens) <= 2:
            return buf
        trimmed = b" ".join(tokens[:1] + tokens[-1:])
        return trimmed

    def queue_new_entry(self, buf: bytes, coverage: Iterable[int]) -> bool:
        discovered = False
        for token in re.findall(rb"[A-Za-z0-9]{2,8}", buf):
            if token not in self.tokens:
                self.tokens.append(token)
                discovered = True
        return discovered

    def describe(self) -> str:
        return "GrammarMutator"


class CmpLogMutator(CustomMutator):
    """CmpLog/RedQueen-style mutator using recorded comparison operands."""

    name = "cmplog"

    def __init__(self, seed: int = 42, operands: Optional[Sequence[bytes]] = None):
        self.operands = list(operands or (b"MZ", b"\x30\x80", b"\x4d\x5a", b"AAAA"))
        super().__init__(seed=seed)

    def record_operand(self, operand: bytes):
        if operand and operand not in self.operands:
            self.operands.append(operand)

    def record_comparison(self, left: bytes, right: bytes):
        self.record_operand(left)
        self.record_operand(right)

    def fuzz(self, buf: bytes, add_buf: bytes = b"") -> bytes:
        operand = self.operands[int(self.rng.randint(0, len(self.operands)))]
        if not buf:
            return operand
        pos = int(self.rng.randint(0, len(buf) + 1))
        if pos + len(operand) <= len(buf):
            return buf[:pos] + operand + buf[pos + len(operand):]
        return (buf + operand + add_buf)[: max(len(buf), len(operand))]

    def fuzz_count(self, buf: bytes) -> int:
        return max(1, min(len(self.operands), 4))

    def havoc_mutation(self, buf: bytes, max_size: int) -> bytes:
        mutated = buf
        replacements = max(1, min(3, len(self.operands)))
        for _ in range(replacements):
            mutated = self.fuzz(mutated)
        return mutated[:max_size]

    def havoc_mutation_probability(self) -> float:
        return 0.25

    def trim(self, buf: bytes) -> bytes:
        for operand in sorted(self.operands, key=len, reverse=True):
            while buf.count(operand) > 1:
                position = buf.find(operand)
                buf = buf[:position] + buf[position + len(operand):]
        return buf

    def queue_new_entry(self, buf: bytes, coverage: Iterable[int]) -> bool:
        discovered = False
        for width in (2, 4):
            for pos in range(0, max(0, len(buf) - width + 1)):
                candidate = buf[pos:pos + width]
                if candidate not in self.operands and any(byte != candidate[0] for byte in candidate):
                    self.operands.append(candidate)
                    discovered = True
        return discovered

    def describe(self) -> str:
        return "CmpLogMutator"

