"""AFL++ MOpt scheduling and power-schedule ensemble."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Callable, Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

from fuzzsim.aflfast_schedules import COE, EXPLORE, FAST, LINEAR, LIN, QUAD, EnergyComputer
from fuzzsim.aflpp_custom_mutator import MutatorRegistry
from fuzzsim.mutation import INTERESTING_8, arith_add, arith_sub, bit_flip, byte_flip, random_byte


MOPT_OPERATORS = (
    "bit_flip",
    "byte_flip",
    "arith_add",
    "arith_sub",
    "interesting",
    "random_byte",
    "havoc_1",
    "havoc_2",
)


def apply_operator(data: bytes, operator: str, rng: np.random.RandomState) -> bytes:
    """Apply one mutation operator from the MOpt operator set."""
    if not data:
        data = b"\x00"
    pos = int(rng.randint(0, len(data)))

    if operator == "bit_flip":
        return bit_flip(data, int(rng.randint(0, len(data) * 8)), 1)
    if operator == "byte_flip":
        return byte_flip(data, pos, 1)
    if operator == "arith_add":
        return arith_add(data, pos, int(rng.randint(1, 36)))
    if operator == "arith_sub":
        return arith_sub(data, pos, int(rng.randint(1, 36)))
    if operator == "interesting":
        buf = bytearray(data)
        buf[pos] = INTERESTING_8[int(rng.randint(0, len(INTERESTING_8)))] & 0xFF
        return bytes(buf)
    if operator == "random_byte":
        return random_byte(data, pos, rng)
    if operator == "havoc_1":
        return random_byte(bit_flip(data, int(rng.randint(0, len(data) * 8)), 1), pos, rng)
    if operator == "havoc_2":
        mutated = byte_flip(data, pos, 1)
        mutated = arith_add(mutated, pos, int(rng.randint(1, 36)))
        return mutated
    raise ValueError(f"unknown MOpt operator: {operator}")


@dataclass
class Particle:
    position: List[float]
    velocity: List[float]
    personal_best: List[float]
    personal_best_fitness: float = float("-inf")
    fitness_history: List[float] = field(default_factory=list)


class MOptScheduler:
    """Particle Swarm Optimization scheduler used by AFL++ MOpt."""

    def __init__(
        self,
        operators: Sequence[str] = MOPT_OPERATORS,
        swarm_size: int = 4,
        pilot_iterations: int = 3,
        inertia_weight: float = 0.7,
        cognitive: float = 1.5,
        social: float = 1.5,
        seed: int = 42,
    ):
        self.operators = list(operators)
        self.swarm_size = swarm_size
        self.pilot_iterations = pilot_iterations
        self.inertia_weight = inertia_weight
        self.cognitive = cognitive
        self.social = social
        self.rng = np.random.RandomState(seed)
        self.phase = "pilot"
        self.operator_stats: Dict[str, Dict[str, float]] = {
            operator: {"attempts": 0.0, "successes": 0.0}
            for operator in self.operators
        }
        uniform = [1.0 / len(self.operators)] * len(self.operators)
        self.particles = [
            Particle(
                position=list(uniform),
                velocity=[0.0] * len(self.operators),
                personal_best=list(uniform),
            )
            for _ in range(self.swarm_size)
        ]
        self.global_best_position = list(uniform)
        self.global_best_fitness = float("-inf")
        self.fitness_history: List[float] = []

    @staticmethod
    def _bounded_normalize(values: Sequence[float]) -> List[float]:
        clipped = np.clip(np.array(values, dtype=float), 0.02, 0.50)
        clipped /= clipped.sum()

        for _ in range(8):
            low = clipped < 0.02
            high = clipped > 0.50
            if not low.any() and not high.any():
                break
            clipped[low] = 0.02
            clipped[high] = 0.50
            remaining = 1.0 - clipped.sum()
            free = ~(low | high)
            if free.any():
                free_total = clipped[free].sum()
                if free_total == 0.0:
                    clipped[free] = remaining / free.sum()
                else:
                    clipped[free] += remaining * (clipped[free] / free_total)
            else:
                clipped /= clipped.sum()
        return clipped.tolist()

    def distribution(self) -> Dict[str, float]:
        return dict(zip(self.operators, self.global_best_position))

    def sample_operator(self, probabilities: Optional[Sequence[float]] = None) -> str:
        probs = np.array(probabilities or self.global_best_position, dtype=float)
        probs = probs / probs.sum()
        index = int(self.rng.choice(len(self.operators), p=probs))
        return self.operators[index]

    def record_result(self, operator: str, success: bool):
        stats = self.operator_stats[operator]
        stats["attempts"] += 1.0
        if success:
            stats["successes"] += 1.0

    def run_pilot(self, fitness_fn: Callable[[str], float]) -> Dict[str, float]:
        averages: Dict[str, float] = {}
        for operator in self.operators:
            scores = []
            for _ in range(self.pilot_iterations):
                score = float(fitness_fn(operator))
                scores.append(score)
                self.record_result(operator, score > 0.0)
            averages[operator] = sum(scores) / len(scores) if scores else 0.0

        base = [max(0.02, averages[operator]) for operator in self.operators]
        normalized = self._bounded_normalize(base)
        for particle in self.particles:
            particle.position = list(normalized)
            particle.velocity = [0.0] * len(normalized)
            particle.personal_best = list(normalized)
            particle.personal_best_fitness = sum(base)
            particle.fitness_history.append(sum(base))

        self.global_best_position = list(normalized)
        self.global_best_fitness = sum(base)
        self.fitness_history.append(self.global_best_fitness)
        self.phase = "core"
        return averages

    def _record_particle_fitness(self, particle: Particle, fitness: float):
        particle.fitness_history.append(fitness)
        if fitness > particle.personal_best_fitness:
            particle.personal_best_fitness = fitness
            particle.personal_best = list(particle.position)
        if fitness > self.global_best_fitness:
            self.global_best_fitness = fitness
            self.global_best_position = list(particle.position)
        self.fitness_history.append(self.global_best_fitness)

    def core_step(self, fitness_fn: Callable[[str, Sequence[float]], float]):
        if self.phase != "core":
            raise RuntimeError("run_pilot() must be called before core_step()")

        for particle in self.particles:
            new_velocity: List[float] = []
            new_position: List[float] = []
            for index in range(len(self.operators)):
                r1 = float(self.rng.rand())
                r2 = float(self.rng.rand())
                velocity = (
                    self.inertia_weight * particle.velocity[index]
                    + self.cognitive * r1 * (particle.personal_best[index] - particle.position[index])
                    + self.social * r2 * (self.global_best_position[index] - particle.position[index])
                )
                velocity = min(max(velocity, -0.3), 0.3)
                new_velocity.append(velocity)
                new_position.append(particle.position[index] + velocity)

            particle.velocity = new_velocity
            particle.position = self._bounded_normalize(new_position)
            operator = self.sample_operator(particle.position)
            fitness = float(fitness_fn(operator, particle.position))
            self.record_result(operator, fitness > 0.0)
            self._record_particle_fitness(particle, fitness)

    def converged(self, window: int = 5, tolerance: float = 1e-3) -> bool:
        if len(self.fitness_history) < window:
            return False
        recent = self.fitness_history[-window:]
        return max(recent) - min(recent) <= tolerance


class PowerScheduleEnsemble:
    """Rotate through AFLFast-derived schedules once per queue cycle."""

    def __init__(
        self,
        schedules: Sequence[str] = (FAST, COE, EXPLORE, QUAD, LIN),
        energy_computer: Optional[EnergyComputer] = None,
    ):
        self.schedules = list(schedules)
        self.energy_computer = energy_computer or EnergyComputer()
        self.index = 0

    def current_schedule(self) -> str:
        return self.schedules[self.index]

    def advance(self) -> str:
        self.index = (self.index + 1) % len(self.schedules)
        return self.current_schedule()

    def schedule_for_cycle(self, cycle: int) -> str:
        return self.schedules[cycle % len(self.schedules)]

    def compute_energy(self, frequency: float, selection_count: float) -> float:
        return self.energy_computer.compute(
            self.current_schedule(),
            frequency=frequency,
            selection_count=selection_count,
            beta=self.energy_computer.beta,
        )


class AFLPlusPlusHarness:
    """Small glue layer for custom mutators, MOpt, and schedule rotation."""

    def __init__(
        self,
        registry: MutatorRegistry,
        mopt: MOptScheduler,
        ensemble: PowerScheduleEnsemble,
        seed: int = 42,
    ):
        self.registry = registry
        self.mopt = mopt
        self.ensemble = ensemble
        self.rng = np.random.RandomState(seed)

    def mutate(self, data: bytes, add_buf: bytes = b"", max_size: int = 64) -> Tuple[str, bytes]:
        mutator = self.registry.select(self.rng)
        buf = mutator.fuzz(data, add_buf)
        if self.rng.rand() < mutator.havoc_mutation_probability():
            buf = mutator.havoc_mutation(buf, max_size)
        buf = mutator.post_process(buf)
        return mutator.describe(), buf[:max_size]
